begin;
create extension if not exists pgtap with schema extensions;
select plan(25);
insert into public.organizations (id,name) values ('f1000000-0000-4000-8000-000000000001','Replenishment');
insert into public.organization_billing (org_id,plan,status,billing_interval) values ('f1000000-0000-4000-8000-000000000001','operations','active','monthly');
insert into public.org_users (org_id,user_id,role) values ('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','owner');
insert into public.materials (id,org_id,sku,name,min_stock) values ('f3000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','REP','Bolts',10);
insert into public.locations (id,org_id,name) values ('f4000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','Main');
insert into public.suppliers (id,org_id,name) values ('f5000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','Supplier');
insert into public.inventory_balances (org_id,material_id,location_id,quantity) values ('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001',8);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f2000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.set_replenishment_settings('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',10,50,'f5000000-0000-4000-8000-000000000001')$$,'manager configures policy');
create temporary table rep_row as select * from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC');
select is((select suggested_order from rep_row),'42.000','target minus stock');
select is((select on_hand from rep_row),'8.000','physical stock separate');
select is((select state from rep_row),'ready','ready for review');
select throws_ok($$select public.set_replenishment_settings('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',10,9,null)$$,'22023','Target must be at least minimum','invalid target rejected');
create temporary table rep_input as select jsonb_build_object('request_id','f6000000-0000-4000-8000-000000000001','required_by',current_date+14,'timezone','UTC','rows',jsonb_build_array(jsonb_build_object('material_id',material_id,'snapshot_token',snapshot_token,'supplier_id',supplier_id,'currency','EUR','quantity','42','acknowledge_incoming',false))) as payload from rep_row;
create temporary table rep_result as select public.create_replenishment_drafts('f1000000-0000-4000-8000-000000000001',payload) as result from rep_input;
select is((select count(*) from public.purchase_orders where org_id='f1000000-0000-4000-8000-000000000001'),1::bigint,'one draft');
select is((select status::text from public.purchase_orders where org_id='f1000000-0000-4000-8000-000000000001'),'draft','ordinary draft lifecycle');
select is((select quantity from public.inventory_balances where material_id='f3000000-0000-4000-8000-000000000001'),8.000::numeric,'draft does not change stock');
select is((select suggested_order from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'0.000','draft prevents repeated recommendation');
select is((select confirmed_incoming from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'0.000','draft is not confirmed supply');
select is((select public.create_replenishment_drafts('f1000000-0000-4000-8000-000000000001',payload) from rep_input),(select result from rep_result),'same key replays exact result');
select throws_ok($$select public.create_replenishment_drafts('f1000000-0000-4000-8000-000000000001',jsonb_set(payload,'{rows,0,quantity}','"1"')) from rep_input$$,'40001','Request ID already used with different input','changed payload rejected');
select throws_ok($$select public.create_replenishment_drafts('f1000000-0000-4000-8000-000000000001',jsonb_set(payload,'{request_id}','"f6000000-0000-4000-8000-000000000002"')) from rep_input$$,'40001','Recommendations changed; review again','second manager stale snapshot rejected');
select public.transition_purchase_order_status('f1000000-0000-4000-8000-000000000001',(select id from public.purchase_orders where org_id='f1000000-0000-4000-8000-000000000001'),'cancelled');
select is((select suggested_order from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'42.000','cancelling releases planned quantity');
reset role;
update public.materials set min_stock=2,target_stock=5.5 where id='f3000000-0000-4000-8000-000000000001';
update public.inventory_balances set quantity=1.25 where material_id='f3000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select suggested_order from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'4.250','fractional quantity preserved');
create temporary table incoming_po as select public.create_purchase_order_with_lines('f1000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001','REP-INCOMING','EUR','[{"material_id":"f3000000-0000-4000-8000-000000000001","quantity_ordered":0.5}]',current_date+2) po;
select public.transition_purchase_order_status('f1000000-0000-4000-8000-000000000001',(select (po->>'id')::uuid from incoming_po),'sent');
select public.create_purchase_order_with_lines('f1000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001','REP-PLANNED','EUR','[{"material_id":"f3000000-0000-4000-8000-000000000001","quantity_ordered":0.25}]');
select is((select suggested_order from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'3.500','fractional stock incoming and draft arithmetic');
select is((select confirmed_incoming from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'0.500','sent PO contributes only remaining quantity');
select is((select suggested_order from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date,'UTC')),'4.000','later supply is excluded from horizon');
select ok((select uncertain from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date,'UTC')),'late supply is explicitly uncertain');
select ok((select draft_warning from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'undated drafts have a separate planning warning');
select is((public.list_replenishment('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC','all',1,1)->>'total')::integer,1,'counts precede pagination');
select throws_ok($$select public.create_replenishment_drafts('f1000000-0000-4000-8000-000000000001',jsonb_build_object('request_id','f6000000-0000-4000-8000-000000000003','required_by',current_date,'timezone','UTC','rows',jsonb_build_array(jsonb_build_object('material_id',material_id,'snapshot_token',snapshot_token,'supplier_id',supplier_id,'currency','EUR','quantity','1','acknowledge_incoming',false)))) from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date,'UTC')$$,'22023','Review uncertain incoming orders','uncertain supply requires acknowledgment');
select public.set_replenishment_settings('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',2,5.5,'f5000000-0000-4000-8000-000000000001','USD');
select is((select currency from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')),'USD','purchasing currency can be explicitly configured');
select set_config('request.jwt.claims','{"sub":"f2000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select * from public.replenishment_rows('f1000000-0000-4000-8000-000000000001',current_date+14,'UTC')$$,'42501','Organization membership required','other workspace denied');
select throws_ok($$select public.set_replenishment_settings('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',2,5,null)$$,'42501','Manager write access required','non-manager denied');
select * from finish();
rollback;

